// Cargar reglas de clasificación
const rules = {
  "rules": [
    {
      "category": "client",
      "mapped_category": "soporte",
      "name": "Cliente",
      "description": "Emails de clientes actuales o en proceso que requieren seguimiento, gestión de cita, documentación o respuesta operativa.",
      "keywords": ["pedido", "problema", "incidencia", "seguimiento", "mi cita", "mi pedido", "documentación", "cambiar cita", "adjunto documentación"]
    },
    {
      "category": "billing",
      "mapped_category": "facturacion",
      "name": "Facturas",
      "description": "Emails relacionados con facturas, pagos, presupuestos, administración o proveedores.",
      "keywords": ["factura", "pago", "proveedor", "presupuesto", "abono", "recibo"]
    },
    {
      "category": "lead",
      "mapped_category": "leads",
      "name": "Lead",
      "description": "Emails de personas o empresas que todavía no son clientes y solicitan información, precio o contratación.",
      "keywords": ["información", "presupuesto", "precio", "tarifa", "me interesa", "quisiera saber", "solicitar información", "cómo funciona", "contratar", "consulta"]
    },
    {
      "category": "publicidad",
      "mapped_category": "publicidad",
      "name": "Publicidad",
      "description": "Emails irrelevantes, promocionales o no deseados que no aportan valor al negocio.",
      "keywords": ["seo", "posicionamiento", "oferta", "marketing", "publicidad", "promoción", "unsubscribe", "gratis", "descuento masivo"]
    },
    {
      "category": "incidencias",
      "mapped_category": "incidencias",
      "name": "Incidencias",
      "description": "Problemas técnicos urgentes, errores o fallos que requieren atención inmediata.",
      "keywords": ["error", "fallo", "no funciona", "urgente", "crítico", "caído", "roto"]
    }
  ]
};

return [{
  json: {
    ...$input.item.json,
    classification_rules: rules
  }
}];

function normalizeText(text) {
  return (text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[¿?.,;:()"'\[\]]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const subject = normalizeText($json.subject || '');
const body = normalizeText($json.body || '');
const fullText = `${subject} ${body}`;

const rules = $json.classification_rules?.rules || [];

let bestMatch = null;
let highestScore = 0;

// Evaluar cada regla
for (const rule of rules) {
  let score = 0;
  const keywords = rule.keywords || [];

  // Contar keywords que coinciden
  for (const keyword of keywords) {
    const normalizedKeyword = normalizeText(keyword);

    // Verificar en subject (vale más)
    if (subject.includes(normalizedKeyword)) {
      score += 3;
    }

    // Verificar en body
    if (body.includes(normalizedKeyword)) {
      score += 1;
    }
  }

  // Si este es el mejor score hasta ahora
  if (score > highestScore) {
    highestScore = score;
    bestMatch = rule;
  }
}

// Determinar confianza
let confidence = 'none';
let suggestedCategory = 'otros';
let classificationMethod = 'none';

if (bestMatch && highestScore >= 5) {
  // Alta confianza: 5+ keywords
  confidence = 'high';
  suggestedCategory = bestMatch.mapped_category;
  classificationMethod = 'rules';
} else if (bestMatch && highestScore >= 2) {
  // Media confianza: 2-4 keywords
  confidence = 'medium';
  suggestedCategory = bestMatch.mapped_category;
  classificationMethod = 'rules_low_confidence';
}

return [{
  json: {
    ...$input.item.json,
    rule_classification: {
      category: suggestedCategory,
      confidence: confidence,
      score: highestScore,
      matched_rule: bestMatch?.name || 'none',
      method: classificationMethod
    }
  }
}];

const clientId = $input.first().json.client_id;

const allClients = $input.all();

const match = allClients.find(item => item.json.client_id === clientId);

if (!match) {
  throw new Error(`Cliente no encontrado: ${clientId}`);
}

return [match];

const raw = $json.text || $json.response || $json.output || '';
const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  return [{
    json: {
      categoria: 'otro',
      prioridad: 'media',
      resumen: 'No se pudo analizar el correo automáticamente.',
      intencion: 'Revisión manual',
      requiere_respuesta: true
    }
  }];
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch {
  parsed = {
    categoria: 'otro',
    prioridad: 'media',
    resumen: 'JSON inválido devuelto por el modelo.',
    intencion: 'Revisión manual',
    requiere_respuesta: true
  };
}

const categoriasValidas = ['ventas', 'leads', 'soporte', 'facturacion', 'incidencias', 'publicidad', 'otro'];
const prioridadesValidas = ['baja', 'media', 'alta'];

parsed.categoria = categoriasValidas.includes(parsed.categoria) ? parsed.categoria : 'otro';
parsed.prioridad = prioridadesValidas.includes(parsed.prioridad) ? parsed.prioridad : 'media';
parsed.resumen = parsed.resumen || 'Sin resumen';
parsed.intencion = parsed.intencion || 'Sin intención clara';
parsed.requiere_respuesta = typeof parsed.requiere_respuesta === 'boolean' ? parsed.requiere_respuesta : true;

return [{ json: parsed }];

const config = {};

for (const item of items) {
  const clave = item.json.clave;
  const valor = item.json.valor;

  if (clave) {
    config[clave] = valor || '';
  }
}

return [
  {
    json: config
  }
];

function limpiarTexto(texto) {
  return (texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function contieneAlguna(texto, palabras) {
  return palabras.some(p => texto.includes(p));
}

function puntuacionFaq(faq, text, categoriaEmail) {
  let score = 0;

  const pregunta = limpiarTexto(faq.pregunta_tipo);
  const respuesta = limpiarTexto(faq.respuesta_oficial);
  const cuandoUsar = limpiarTexto(faq.cuando_usar);
  const cuandoNoUsar = limpiarTexto(faq.cuando_no_usar);
  const categoriaFaq = limpiarTexto(faq.categoria_origen);

  const bloques = [pregunta, respuesta, cuandoUsar, cuandoNoUsar, categoriaFaq];

  for (const bloque of bloques) {
    const palabras = bloque.split(' ').filter(p => p.length > 3);
    for (const palabra of palabras) {
      if (text.includes(palabra)) score += 1;
    }
  }

  if (categoriaEmail && categoriaFaq.includes(categoriaEmail)) {
    score += 4;
  }

  const esFacturacion = contieneAlguna(text, [
    'factura', 'facturacion', 'cargo', 'cobro', 'pago', 'importe', 'recibo'
  ]);

  const esPrecio = contieneAlguna(text, [
    'precio', 'presupuesto', 'coste', 'tarifa'
  ]);

  const esFormacion = contieneAlguna(text, [
    'formacion', 'workshop', 'workshops', 'taller'
  ]);

  const esSoporte = contieneAlguna(text, [
    'soporte', 'ayuda', 'problema', 'error', 'incidencia'
  ]);

  const esIA = contieneAlguna(text, [
    'ia', 'inteligencia artificial'
  ]);

  if (esFacturacion) {
    if (
      contieneAlguna(pregunta, ['factura', 'facturacion', 'cargo', 'cobro', 'pago']) ||
      contieneAlguna(respuesta, ['factura', 'facturacion', 'cargo', 'cobro', 'pago']) ||
      contieneAlguna(cuandoUsar, ['factura', 'facturacion', 'cargo', 'cobro', 'pago']) ||
      categoriaFaq.includes('facturacion')
    ) {
      score += 6;
    }

    if (categoriaFaq.includes('lead') || categoriaFaq.includes('ventas')) {
      score -= 4;
    }
  }

  if (esPrecio) {
    if (
      contieneAlguna(pregunta, ['precio', 'tarifa', 'coste', 'presupuesto']) ||
      contieneAlguna(respuesta, ['precio', 'tarifa', 'coste', 'presupuesto'])
    ) {
      score += 5;
    }
  }

  if (esFormacion) {
    if (
      contieneAlguna(pregunta, ['formacion', 'workshop', 'taller']) ||
      contieneAlguna(respuesta, ['formacion', 'workshop', 'taller'])
    ) {
      score += 5;
    }
  }

  if (esSoporte) {
    if (
      categoriaFaq.includes('soporte') ||
      contieneAlguna(cuandoUsar, ['soporte', 'ayuda', 'problema', 'error', 'incidencia'])
    ) {
      score += 4;
    }
  }

  if (esIA) {
    if (
      contieneAlguna(pregunta, ['ia', 'inteligencia artificial']) ||
      contieneAlguna(respuesta, ['ia', 'inteligencia artificial'])
    ) {
      score += 3;
    }
  }

  return score;
}

const ctx = $('Build analysis context').first().json;

const text = limpiarTexto([
  ctx.subject || '',
  ctx.body || '',
  ctx.resumen || '',
  ctx.intencion || '',
  ctx.categoria || ''
].join(' '));

const categoriaEmail = limpiarTexto(ctx.categoria || '');

const scored = items
  .filter(item =>
    item.json.faq_id &&
    item.json.pregunta_tipo &&
    item.json.respuesta_oficial
  )
  .map(item => ({
    json: {
      ...item.json,
      categoria: ctx.categoria,
      prioridad: ctx.prioridad,
      resumen: ctx.resumen,
      intencion: ctx.intencion,
      requiere_respuesta: ctx.requiere_respuesta,
      subject: ctx.subject,
      body: ctx.body,
      texto_usado_para_buscar: text,
      categoria_email: categoriaEmail,
      score: puntuacionFaq(item.json, text, categoriaEmail)
    }
  }))
  .sort((a, b) => b.json.score - a.json.score);

const relevantes = scored.filter(item => item.json.score > 0).slice(0, 3);

if (relevantes.length > 0) {
  return relevantes;
}

// fallback: devolver las 3 mejores aunque tengan score 0
const fallback = scored.slice(0, 3).map(item => ({
  json: {
    ...item.json,
    faq_fallback: true
  }
}));

if (fallback.length > 0) {
  return fallback;
}

// fallback final: nunca devolver vacío
return [
  {
    json: {
      categoria: ctx.categoria,
      prioridad: ctx.prioridad,
      resumen: ctx.resumen,
      intencion: ctx.intencion,
      requiere_respuesta: ctx.requiere_respuesta,
      subject: ctx.subject,
      body: ctx.body,
      faq_id: '',
      pregunta_tipo: '',
      respuesta_oficial: '',
      score: 0,
      faq_fallback: true,
      sin_faqs_relevantes: true
    }
  }
];

const faqsValidas = items.filter(item => item.json.faq_id && item.json.respuesta_oficial);

if (faqsValidas.length === 0) {
  return [
    {
      json: {
        faqs_contexto: '',
        faq_ids_usadas: '',
        faqs_raw: [],
        sin_faqs_relevantes: true
      }
    }
  ];
}

const faqIds = faqsValidas.map(item => item.json.faq_id).join(', ');

const faqsTexto = faqsValidas.map((item, i) => {
  const faq = item.json;

  return `FAQ ${i + 1}
ID: ${faq.faq_id || ''}
Categoría origen: ${faq.categoria_origen || ''}
Pregunta tipo: ${faq.pregunta_tipo || ''}
Respuesta oficial: ${faq.respuesta_oficial || ''}
Nivel de detalle: ${faq.nivel_detalle || ''}
Cuándo usar: ${faq.cuando_usar || ''}
Cuándo no usar: ${faq.cuando_no_usar || ''}
Última actualización: ${faq.ultima_actualizacion || ''}
Notas internas: ${faq.notas_internas || ''}
Score: ${faq.score ?? ''}${faq.faq_fallback ? '\nFAQ fallback: true' : ''}`;
}).join('\n\n');

return [
  {
    json: {
      faqs_contexto: faqsTexto,
      faq_ids_usadas: faqIds,
      faqs_raw: faqsValidas.map(item => item.json),
      sin_faqs_relevantes: false
    }
  }
];

function limpiarTexto(texto) {
  return (texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[¿?.,;:()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function contieneAlguna(texto, palabras) {
  return palabras.some(p => texto.includes(p));
}

function scoreHistorico(item, ctx, text) {
  let score = 0;

  const categoriaHist = limpiarTexto(item.categoria || '');
  const intencionHist = limpiarTexto(item.intencion || '');
  const emailHist = limpiarTexto(item.email_original || '');
  const tags = limpiarTexto(item.tags || '');

  // Match por categoría
  if (categoriaHist && categoriaHist.includes(ctx.categoria)) {
    score += 5;
  }

  // Match por intención
  if (intencionHist && intencionHist.includes(ctx.intencion)) {
    score += 4;
  }

  // Coincidencias de palabras
  const palabras = emailHist.split(' ').filter(p => p.length > 4);
  for (const palabra of palabras) {
    if (text.includes(palabra)) score += 1;
  }

  // Tags
  const tagsList = tags.split(',').map(t => t.trim());
  for (const tag of tagsList) {
    if (text.includes(tag)) score += 2;
  }

  // Penalizar si no es reutilizable
  if (item.reutilizable !== 'true' && item.reutilizable !== true) {
    score -= 3;
  }

  return score;
}

// 🔥 contexto actual
const ctx = $('Build analysis context').first().json;

const text = limpiarTexto([
  ctx.subject || '',
  ctx.body || '',
  ctx.resumen || '',
  ctx.intencion || ''
].join(' '));

const scored = items
  .filter(item => item.json.id && item.json.respuesta_aprobada)
  .map(item => {
    const score = scoreHistorico(item.json, ctx, text);

    return {
      json: {
        ...item.json,
        score
      }
    };
  })
  .sort((a, b) => b.json.score - a.json.score);

// respuestas relevantes
const relevantes = scored.filter(item => item.json.score > 0).slice(0, 3);

if (relevantes.length > 0) {
  return relevantes;
}

// fallback: mejores aunque score 0
const fallback = scored.slice(0, 2).map(item => ({
  json: {
    ...item.json,
    historico_fallback: true
  }
}));

if (fallback.length > 0) {
  return fallback;
}

// fallback final
return [
  {
    json: {
      id: '',
      respuesta_aprobada: '',
      score: 0,
      historico_fallback: true,
      sin_historico_relevante: true
    }
  }
];

const historicoValido = items.filter(item =>
  item.json.id && item.json.respuesta_aprobada
);

if (historicoValido.length === 0) {
  return [
    {
      json: {
        respuestas_historicas_contexto: '',
        historial_ids_usados: '',
        historico_raw: [],
        sin_historico_relevante: true
      }
    }
  ];
}

const historialIds = historicoValido.map(item => item.json.id).join(', ');

const historicoTexto = historicoValido.map((item, i) => {
  const h = item.json;

  return `RESPUESTA HISTÓRICA ${i + 1}
ID: ${h.id || ''}
Categoría: ${h.categoria || ''}
Intención: ${h.intencion || ''}
Email original: ${h.email_original || ''}
Respuesta aprobada: ${h.respuesta_aprobada || ''}
Acción final: ${h.accion_final || ''}
Reutilizable: ${h.reutilizable || ''}
Tags: ${h.tags || ''}
Fecha: ${h.fecha || ''}
Score: ${h.score ?? ''}${h.historico_fallback ? '\nHistórico fallback: true' : ''}`;
}).join('\n\n');

return [
  {
    json: {
      respuestas_historicas_contexto: historicoTexto,
      historial_ids_usados: historialIds,
      historico_raw: historicoValido.map(item => item.json),
      sin_historico_relevante: false
    }
  }
];

const ctx = $('Build analysis context').first().json;

const email = [
  ctx.subject || '',
  ctx.body || '',
  ctx.resumen || '',
  ctx.intencion || '',
  ctx.categoria || ''
].join(' ').toLowerCase();

let accion = 'to_reply';
let policy_id = 'default';
let motivo = 'Sin política especial aplicada';

if (
  email.includes('precio') ||
  email.includes('coste') ||
  email.includes('presupuesto') ||
  email.includes('tarifa')
) {
  accion = 'to_waiting';
  policy_id = 'POLICY_PRECIO';
  motivo = 'Pregunta sobre precios o presupuesto';
}

if (
  email.includes('datos') ||
  email.includes('rgpd') ||
  email.includes('privacidad') ||
  email.includes('confidencial')
) {
  accion = 'to_sensitive';
  policy_id = 'POLICY_DATOS';
  motivo = 'Tema sensible relacionado con datos o privacidad';
}

return [
  {
    json: {
      accion_final: accion,
      policy_id,
      policy_motivo: motivo
    }
  }
];

const texto = $json.text || $json.response || $json.output || '';

const limpio = texto
  .replace(/\\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/=\n/g, '')
  .replace(/=/g, '')
  .replace(/^Asunto:\s.*$/gmi, '')
  .trim();

return [
  {
    json: {
      ...$json,
      draft_limpio: limpio
    }
  }
];

// Obtener categoría del email actual
const categoria = $json.categoria || 'otros';

// Obtener configuración del cliente
const clientConfig = $('Filter client routing').first().json;

// Construir nombre del campo dinámicamente
const emailField = `review_email_${categoria}`;

// Obtener email específico, con fallback a review_email genérico
const reviewEmail = clientConfig[emailField] || clientConfig.review_email || 'agusmadevelop@gmail.com';

// Obtener credencial para enviar la revisión
const reviewCredential = clientConfig.review_credential_name || clientConfig.gmail_credential_name || 'gmail_cliente_1';

return [{
  json: {
    ...$input.item.json,
    review_email_final: reviewEmail,
    review_credential_final: reviewCredential
  }
}];

