const categoria = $('Build analysis context').first().json.categoria || 'otros';

const allLabels = items || [];

let foundLabelId = '';
let labelName = '';
let labelFound = false;

// Buscar label que coincida con la categoría
for (const item of allLabels) {
  const name = (item.json.name || '').toLowerCase().trim();

  if (name === categoria) {
    foundLabelId = item.json.id || '';
    labelName = item.json.name || '';
    labelFound = true;
    break;
  }
}

return [{
  json: {
    ...$('Build analysis context').first().json,
    category_label_id: foundLabelId,
    category_label_name: labelName,
    label_found: labelFound
  }
}];
